'use client';

import { useState, useEffect } from 'react';

interface ProjectSceneProps {
  screenshotUrl: string;
  isHovered: boolean;
}

export default function ProjectScene({ screenshotUrl, isHovered }: ProjectSceneProps) {
  const [rotation, setRotation] = useState({ x: 0, y: 0 });
  const [position, setPosition] = useState({ y: 0 });

  // Animate the laptop based on hover state
  useEffect(() => {
    let animationFrameId: number;
    
    const animate = () => {
      // Subtle floating animation
      const floatOffset = Math.sin(Date.now() * 0.001) * 0.1;
      setPosition({ y: floatOffset });
      
      // Tilt animation when hovered
      if (isHovered) {
        setRotation({
          x: -0.1,
          y: 0.05
        });
      } else {
        setRotation({
          x: 0,
          y: 0
        });
      }
      
      animationFrameId = requestAnimationFrame(animate);
    };
    
    animate();
    
    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [isHovered]);

  return (
    <div data-component-id="src\components\three\ProjectScene.tsx:47:4" data-component-path="src\components\three\ProjectScene.tsx" data-component-line="47" data-component-file="ProjectScene.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22w-full%20h-full%20flex%20items-center%20justify-center%20bg-gradient-to-br%20from-gray-900%20to-black%20rounded-t-lg%20overflow-hidden%22%7D" className="w-full h-full flex items-center justify-center bg-gradient-to-br from-gray-900 to-black rounded-t-lg overflow-hidden">
      {/* Laptop base */}
      <div data-component-id="src\components\three\ProjectScene.tsx:49:6" data-component-path="src\components\three\ProjectScene.tsx" data-component-line="49" data-component-file="ProjectScene.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22relative%20w-64%20h-40%22%7D" 
        className="relative w-64 h-40"
        style={{
          transform: `translateY(${position.y}px) rotateX(${rotation.x}rad) rotateY(${rotation.y}rad)`,
          transition: 'transform 0.3s ease-out'
        }}
      >
        {/* Laptop screen */}
        <div data-component-id="src\components\three\ProjectScene.tsx:57:8" data-component-path="src\components\three\ProjectScene.tsx" data-component-line="57" data-component-file="ProjectScene.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22absolute%20top-0%20left-1%2F2%20transform%20-translate-x-1%2F2%20w-56%20h-32%20bg-gray-800%20rounded-t-md%20overflow-hidden%20border-2%20border-gray-700%22%7D" className="absolute top-0 left-1/2 transform -translate-x-1/2 w-56 h-32 bg-gray-800 rounded-t-md overflow-hidden border-2 border-gray-700">
          {/* Screen content */}
          <div data-component-id="src\components\three\ProjectScene.tsx:59:10" data-component-path="src\components\three\ProjectScene.tsx" data-component-line="59" data-component-file="ProjectScene.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22w-full%20h-full%20bg-cover%20bg-center%22%7D" 
            className="w-full h-full bg-cover bg-center"
            style={{ backgroundImage: `url(${screenshotUrl})` }}
          />
          {/* Screen reflection */}
          <div data-component-id="src\components\three\ProjectScene.tsx:64:10" data-component-path="src\components\three\ProjectScene.tsx" data-component-line="64" data-component-file="ProjectScene.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22absolute%20top-0%20left-0%20w-full%20h-full%20bg-gradient-to-b%20from-white%2F10%20to-transparent%20pointer-events-none%22%7D" className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-white/10 to-transparent pointer-events-none"></div>
        </div>
        
        {/* Laptop base */}
        <div data-component-id="src\components\three\ProjectScene.tsx:68:8" data-component-path="src\components\three\ProjectScene.tsx" data-component-line="68" data-component-file="ProjectScene.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22absolute%20bottom-0%20left-1%2F2%20transform%20-translate-x-1%2F2%20w-60%20h-4%20bg-gray-900%20rounded-b-md%20border-2%20border-gray-700%22%7D" className="absolute bottom-0 left-1/2 transform -translate-x-1/2 w-60 h-4 bg-gray-900 rounded-b-md border-2 border-gray-700">
          {/* Keyboard */}
          <div data-component-id="src\components\three\ProjectScene.tsx:70:10" data-component-path="src\components\three\ProjectScene.tsx" data-component-line="70" data-component-file="ProjectScene.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22absolute%20top-1%20left-2%20right-2%20h-2%20flex%20flex-wrap%20gap-0.5%22%7D" className="absolute top-1 left-2 right-2 h-2 flex flex-wrap gap-0.5">
            {[...Array(20)].map((_, i) => (
              <div data-component-id="src\components\three\ProjectScene.tsx:72:14" data-component-path="src\components\three\ProjectScene.tsx" data-component-line="72" data-component-file="ProjectScene.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22w-1%20h-1%20bg-gray-700%20rounded-sm%22%7D" key={i} className="w-1 h-1 bg-gray-700 rounded-sm"></div>
            ))}
          </div>
        </div>
        
        {/* Hinge */}
        <div data-component-id="src\components\three\ProjectScene.tsx:78:8" data-component-path="src\components\three\ProjectScene.tsx" data-component-line="78" data-component-file="ProjectScene.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22absolute%20top-32%20left-1%2F2%20transform%20-translate-x-1%2F2%20w-1%20h-1%20bg-gray-700%20rounded-full%22%7D" className="absolute top-32 left-1/2 transform -translate-x-1/2 w-1 h-1 bg-gray-700 rounded-full"></div>
      </div>
    </div>
  );
}